pm.test('Status code is 200', function () { pm.response.to.have.status(200); });
pm.test('Response is JSON', function () { pm.expect(pm.response.headers.get('Content-Type') || '').to.include('application/json'); });
pm.test('Response body is an array', function () { 
    const jsonData = pm.response.json();
    pm.expect(jsonData.data.notes).to.be.an('array'); });
pm.test('Each returned note has the required fields', function () {
    const jsonData = pm.response.json();
    jsonData.data.notes.forEach(function (note) {
    pm.expect(note).to.have.property('id');
    pm.expect(note).to.have.property('title');
    pm.expect(note).to.have.property('content');
    pm.expect(note).to.have.property('createdAt');
    pm.expect(note).to.have.property('updatedAt');
    if (note.attachments !== undefined) pm.expect(note.attachments).to.be.an('array');
  });
});

pm.test('Status code is 201', function () { pm.response.to.have.status(201); });
pm.test('Response contains the created note', function () {
  const jsonData = pm.response.json();
  const note = jsonData.data;
  pm.expect(note).to.have.property('id');
  pm.expect(note.id).to.be.a('string').and.not.empty;
  pm.expect(note.title).to.eql('Postman Shopping List');
  pm.expect(note.content).to.eql('Milk, bread and coffee');
  pm.expect(note).to.have.property('createdAt');
  pm.expect(note).to.have.property('updatedAt');
  pm.expect(Date.parse(note.createdAt)).not.to.be.NaN;
  pm.expect(Date.parse(note.updatedAt)).not.to.be.NaN;
  pm.collectionVariables.set('noteId', note.id);
  pm.collectionVariables.set('createdAt', note.createdAt);
});

