pm.test('Status code is 200', function () { pm.response.to.have.status(200); });
pm.test('Updated note values are returned', function () {
  const jsonData = pm.response.json();
  pm.expect(jsonData.data.id).to.eql(pm.collectionVariables.get('noteId'));
  pm.expect(jsonData.data.title).to.eql('Updated Postman Shopping List');
