pm.test('updatedAt is changed and createdAt is preserved', function () {
  const jsonData = pm.response.json();
    const note = jsonData.data;
  const oldCreatedAt = pm.collectionVariables.get('createdAt');
  if (note.createdAt !== undefined) pm.expect(note.createdAt).to.eql(oldCreatedAt);
  pm.expect(note).to.have.property('updatedAt');
  pm.expect(Date.parse(note.updatedAt)).not.to.be.NaN;
  if (oldCreatedAt) pm.expect(Date.parse(note.updatedAt)).to.be.at.least(Date.parse(oldCreatedAt));
});

