pm.test('Attachment metadata is returned', function () {
  const jsonData = pm.response.json(); 
  const attachment = jsonData.data;
  pm.expect(attachment).to.have.property('id');
  pm.expect(attachment.id).to.be.a('string').and.not.empty;
  pm.expect(attachment).to.have.property('fileName');
  pm.expect(attachment).to.have.property('contentType');
  pm.expect(attachment).to.have.property('url');
  pm.expect(attachment.url).to.be.a('string').and.not.empty;
  pm.collectionVariables.set('attachmentId', attachment.id);
});

pm.test('Status code is 200', function () { pm.response.to.have.status(200); });
pm.test('Created attachment is associated with the note', function () {
  const jsonData = pm.response.json();
    const note = jsonData.data;
  pm.expect(note).to.have.property('attachments');
  pm.expect(note.attachments).to.be.an('array');
  const attachmentId = pm.collectionVariables.get('attachmentId');
  const found = note.attachments.some(function (a) { return a.id === attachmentId; });
  pm.expect(found).to.eql(true);
  if (note.attachmentCount !== undefined) pm.expect(note.attachmentCount).to.eql(note.attachments.length);
});

pm.test('Status code is 200', function () { pm.response.to.have.status(200); });
pm.test('Created note is present with its attachment', function () {
  const jsonData = pm.response.json();
  const notes = jsonData.data.notes;
  const noteId = pm.collectionVariables.get('noteId');
  const attachmentId = pm.collectionVariables.get('attachmentId');
  const note = notes.find(function (n) { return n.id === noteId; });
  pm.expect(note, 'Created note should be present').to.exist;
  pm.expect(note.attachments).to.be.an('array');
  pm.expect(note.attachments.some(function (a) { return a.id === attachmentId; })).to.eql(true);
});

